import{_ as c,C as d,o,c as u,a2 as i,b as n,w as a,a as t,E as r,a3 as s}from"./chunks/framework.CgxQ0r6v.js";const v=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 3","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_II/documentacion/II-IV/Lectura_Catedra_Evaluacion_3.md","filePath":"materias/Proyecto_Sociotecnologico_II/documentacion/II-IV/Lectura_Catedra_Evaluacion_3.md"}'),m={name:"materias/Proyecto_Sociotecnologico_II/documentacion/II-IV/Lectura_Catedra_Evaluacion_3.md"};function g(p,e,b,f,A,C){const l=d("Mermaid");return o(),u("div",null,[e[2]||(e[2]=i('<h1 id="manual-de-estudio-profundo-evaluacion-3" tabindex="-1">Manual de Estudio Profundo: Evaluación 3 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-3" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 3&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-ii-trayecto-ii-trimestre-iv" tabindex="-1">Materia: Proyecto Sociotecnológico II (Trayecto II - Trimestre IV) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-ii-trayecto-ii-trimestre-iv" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico II (Trayecto II - Trimestre IV)&quot;">​</a></h2><h3 id="eje-tematico-planteamiento-del-problema-bajo-el-enfoque-del-marco-logico-eml" tabindex="-1">Eje Temático: Planteamiento del Problema bajo el Enfoque del Marco Lógico (EML) <a class="header-anchor" href="#eje-tematico-planteamiento-del-problema-bajo-el-enfoque-del-marco-logico-eml" aria-label="Permalink to &quot;Eje Temático: Planteamiento del Problema bajo el Enfoque del Marco Lógico (EML)&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-rigurosidad-metodologica-del-eml" tabindex="-1">🧭 Introducción: La Rigurosidad Metodológica del EML <a class="header-anchor" href="#🧭-introduccion-la-rigurosidad-metodologica-del-eml" aria-label="Permalink to &quot;🧭 Introducción: La Rigurosidad Metodológica del EML&quot;">​</a></h2><p>El <strong>Enfoque del Marco Lógico (EML)</strong> es la metodología estándar adoptada por organismos internacionales (CEPAL, PNUD, BID) y por el sistema universitario venezolano (especialmente en los Programas Nacionales de Formación) para la conceptualización, diseño, ejecución y evaluación de proyectos de desarrollo social y tecnológico.</p><p>En el desarrollo de software, el EML evita el error común de programar soluciones aisladas que no atacan la raíz del problema. A través del análisis causa-efecto, el equipo informático se asegura de que cada módulo del sistema informático responda directamente a una causa identificada y contribuya a un fin comunitario superior.</p><hr><h2 id="🌳-capitulo-i-el-arbol-del-problema" tabindex="-1">🌳 CAPÍTULO I: El Árbol del Problema <a class="header-anchor" href="#🌳-capitulo-i-el-arbol-del-problema" aria-label="Permalink to &quot;🌳 CAPÍTULO I: El Árbol del Problema&quot;">​</a></h2><p>El <strong>Árbol del Problema</strong> es una herramienta visual de diagnóstico participativo que permite descomponer una situación negativa en sus componentes estructurales:</p><ul><li><strong>Las Ramas (Copa):</strong> Son los <strong>Efectos</strong> y consecuencias visibles generadas por el problema central en la comunidad.</li><li><strong>El Tronco:</strong> Es el <strong>Problema Central</strong> claramente delimitado (no debe redactarse como la ausencia de una solución, sino como un estado negativo existente).</li><li><strong>Las Raíces:</strong> Son las <strong>Causas</strong> directas e indirectas que originan y alimentan el problema.</li></ul>',11)),(o(),n(s,null,{default:a(()=>[r(l,{id:"mermaid-43",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20subgraph%20EFECTOS%20%5B%22%F0%9F%8D%83%20EFECTOS%20(Consecuencias%20en%20la%20Comunidad)%22%5D%0A%20%20%20%20%20%20%20%20E3%5B%22P%C3%A9rdida%20de%20credibilidad%20institucional%20y%20descontento%20vecinal%22%5D%0A%20%20%20%20%20%20%20%20E1%5B%22Demoras%20cr%C3%ADticas%20en%20la%20asignaci%C3%B3n%20de%20beneficios%20sociales%22%5D%0A%20%20%20%20%20%20%20%20E2%5B%22P%C3%A9rdida%20y%20deterioro%20irreversible%20de%20expedientes%20f%C3%ADsicos%22%5D%0A%20%20%20%20%20%20%20%20E1%20---%20E3%0A%20%20%20%20%20%20%20%20E2%20---%20E3%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20PROBLEMA%20%5B%22%F0%9F%AA%B5%20PROBLEMA%20CENTRAL%22%5D%0A%20%20%20%20%20%20%20%20PC%5B%22Ineficiente%20gesti%C3%B3n%20y%20control%20de%20la%20informaci%C3%B3n%20de%20los%20habitantes%20en%20la%20comunidad%20'X'%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20CAUSAS%20%5B%22%F0%9F%8C%B1%20CAUSAS%20(Ra%C3%ADces%20del%20Problema)%22%5D%0A%20%20%20%20%20%20%20%20C1%5B%22Proceso%20de%20registro%20100%25%20manual%20en%20cuadernos%20y%20hojas%20sueltas%22%5D%0A%20%20%20%20%20%20%20%20C2%5B%22Inexistencia%20de%20un%20repositorio%20centralizado%20de%20datos%22%5D%0A%20%20%20%20%20%20%20%20C3%5B%22Falta%20de%20capacitaci%C3%B3n%20t%C3%A9cnica%20en%20herramientas%20inform%C3%A1ticas%20de%20los%20voceros%22%5D%0A%20%20%20%20%20%20%20%20C11%5B%22Ausencia%20de%20herramientas%20de%20software%20automatizadas%22%5D%20--%3E%20C1%0A%20%20%20%20%20%20%20%20C21%5B%22Falta%20de%20copias%20de%20seguridad%20de%20los%20registros%20comunales%22%5D%20--%3E%20C2%0A%20%20%20%20end%0A%0A%20%20%20%20PROBLEMA%20--%3E%20EFECTOS%0A%20%20%20%20CAUSAS%20--%3E%20PROBLEMA%0A%0A%20%20%20%20style%20EFECTOS%20fill%3A%23450a0a%2Cstroke%3A%23dc2626%2Ccolor%3A%23fff%0A%20%20%20%20style%20PROBLEMA%20fill%3A%2378350f%2Cstroke%3A%23f59e0b%2Ccolor%3A%23fff%0A%20%20%20%20style%20CAUSAS%20fill%3A%23064e3b%2Cstroke%3A%2310b981%2Ccolor%3A%23fff%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=i('<div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>Error típico de redacción:</strong><em>Incorrecto:</em> &quot;El problema central es que no tienen una página web o un sistema.&quot; (Confundir el problema con la solución). <em>Correcto:</em> &quot;Ineficiente control del inventario y lentitud en la dispensación de medicamentos en el Ambulatorio Comunitario.&quot; (El estado negativo que sufre la comunidad).</p></div><hr><h2 id="🎯-capitulo-ii-el-arbol-de-objetivos" tabindex="-1">🎯 CAPÍTULO II: El Árbol de Objetivos <a class="header-anchor" href="#🎯-capitulo-ii-el-arbol-de-objetivos" aria-label="Permalink to &quot;🎯 CAPÍTULO II: El Árbol de Objetivos&quot;">​</a></h2><p>El <strong>Árbol de Objetivos</strong> representa la situación futura deseada cuando el problema haya sido resuelto. Se construye mediante una transformación lógica: <strong>las condiciones negativas del Árbol del Problema se convierten en estados positivos alcanzables</strong>.</p><ul><li><strong>Las Raíces negativas (Causas)</strong> se transforman en <strong>Medios</strong> (los entregables técnicos y componentes del sistema).</li><li><strong>El Tronco negativo (Problema Central)</strong> se transforma en el <strong>Objetivo General</strong> del proyecto.</li><li><strong>Las Ramas negativas (Efectos)</strong> se transforman en los <strong>Fines</strong> (el impacto positivo en la calidad de vida de los habitantes).</li></ul>',5)),(o(),n(s,null,{default:a(()=>[r(l,{id:"mermaid-73",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20subgraph%20FINES%20%5B%22%F0%9F%8C%9F%20FINES%20(Impacto%20Positivo%20Futuro)%22%5D%0A%20%20%20%20%20%20%20%20F3%5B%22Fortalecimiento%20de%20la%20confianza%20comunitaria%20y%20transparencia%20institucional%22%5D%0A%20%20%20%20%20%20%20%20F1%5B%22Optimizaci%C3%B3n%20y%20agilidad%20en%20la%20entrega%20de%20beneficios%20y%20tr%C3%A1mites%22%5D%0A%20%20%20%20%20%20%20%20F2%5B%22Preservaci%C3%B3n%20%C3%ADntegra%20y%20disponibilidad%20inmediata%20de%20la%20informaci%C3%B3n%20hist%C3%B3rica%22%5D%0A%20%20%20%20%20%20%20%20F1%20---%20F3%0A%20%20%20%20%20%20%20%20F2%20---%20F3%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20OBJETIVO%20%5B%22%F0%9F%8E%AF%20OBJETIVO%20GENERAL%22%5D%0A%20%20%20%20%20%20%20%20OG%5B%22Desarrollar%20una%20aplicaci%C3%B3n%20inform%C3%A1tica%20bajo%20est%C3%A1ndares%20de%20software%20libre%20para%20la%20gesti%C3%B3n%20de%20informaci%C3%B3n%20de%20la%20comunidad%20'X'%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20MEDIOS%20%5B%22%F0%9F%9B%A0%EF%B8%8F%20MEDIOS%20(Componentes%20y%20Objetivos%20Espec%C3%ADficos)%22%5D%0A%20%20%20%20%20%20%20%20M1%5B%22Automatizaci%C3%B3n%20del%20registro%20mediante%20formularios%20digitales%20validados%22%5D%0A%20%20%20%20%20%20%20%20M2%5B%22Implementaci%C3%B3n%20de%20una%20base%20de%20datos%20relacional%20segura%20y%20respaldada%22%5D%0A%20%20%20%20%20%20%20%20M3%5B%22Capacitaci%C3%B3n%20y%20transferencia%20tecnol%C3%B3gica%20a%20los%20voceros%20y%20operadores%20comunitarios%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20OBJETIVO%20--%3E%20FINES%0A%20%20%20%20MEDIOS%20--%3E%20OBJETIVO%0A%0A%20%20%20%20style%20FINES%20fill%3A%23064e3b%2Cstroke%3A%2310b981%2Ccolor%3A%23fff%0A%20%20%20%20style%20OBJETIVO%20fill%3A%231e3a8a%2Cstroke%3A%233b82f6%2Ccolor%3A%23fff%0A%20%20%20%20style%20MEDIOS%20fill%3A%230f766e%2Cstroke%3A%2314b8a6%2Ccolor%3A%23fff%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[t(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=i('<hr><h2 id="📄-capitulo-iii-estructura-del-capitulo-i-en-el-1er-informe-de-avance" tabindex="-1">📄 CAPÍTULO III: Estructura del Capítulo I en el 1er Informe de Avance <a class="header-anchor" href="#📄-capitulo-iii-estructura-del-capitulo-i-en-el-1er-informe-de-avance" aria-label="Permalink to &quot;📄 CAPÍTULO III: Estructura del Capítulo I en el 1er Informe de Avance&quot;">​</a></h2><p>El Capítulo I del informe de proyecto de la UPTT consolida el diagnóstico y el planteamiento científico. Debe estructurarse con las siguientes secciones:</p><h3 id="_3-1-descripcion-del-contexto" tabindex="-1">3.1 Descripción del Contexto <a class="header-anchor" href="#_3-1-descripcion-del-contexto" aria-label="Permalink to &quot;3.1 Descripción del Contexto&quot;">​</a></h3><ul><li><strong>Identificación de la Organización:</strong> Razón social, ubicación geográfica (con coordenadas o mapa local), reseña histórica de la comunidad y misión/visión del consejo comunal o institución.</li><li><strong>Estructura Organizativa:</strong> Organigrama de la institución o comisiones del consejo comunal.</li></ul><h3 id="_3-2-planteamiento-del-problema" tabindex="-1">3.2 Planteamiento del Problema <a class="header-anchor" href="#_3-2-planteamiento-del-problema" aria-label="Permalink to &quot;3.2 Planteamiento del Problema&quot;">​</a></h3><ul><li><strong>Contextualización a tres niveles:</strong><ul><li><em>Macro:</em> El avance de la digitalización y el acceso a la tecnología en Venezuela.</li><li><em>Meso:</em> Los retos de gestión de información en las instituciones locales del estado Trujillo.</li><li><em>Micro:</em> La realidad cotidiana de la comunidad seleccionada (respaldada con las estadísticas obtenidas del diagnóstico participativo).</li></ul></li><li><strong>Formulación del Problema:</strong> Pregunta rectora de investigación: <em>¿Cómo optimizar el control y gestión de los datos de los beneficiarios mediante una solución informática libre en la comunidad &#39;X&#39;?</em></li></ul><h3 id="_3-3-objetivos-del-proyecto" tabindex="-1">3.3 Objetivos del Proyecto <a class="header-anchor" href="#_3-3-objetivos-del-proyecto" aria-label="Permalink to &quot;3.3 Objetivos del Proyecto&quot;">​</a></h3><ul><li><strong>Objetivo General:</strong> Comienza con verbo infinitivo (Desarrollar, Diseñar, Implementar, Construir) e indica el qué, el cómo y el para qué.</li><li><strong>Objetivos Específicos:</strong> Siguen el ciclo de ingeniería de software del PST II: <ol><li><em>Diagnosticar</em> los procesos actuales y requerimientos de información de la comunidad.</li><li><em>Diseñar</em> la arquitectura del software y la base de datos relacional bajo estándares UML.</li><li><em>Desarrollar</em> (codificar) los módulos del sistema informático utilizando lenguajes y herramientas abiertas.</li><li><em>Verificar y validar</em> la funcionalidad del sistema mediante casos de prueba formales.</li><li><em>Implantar</em> la aplicación informática y capacitar a los usuarios finales para garantizar su apropiación social.</li></ol></li></ul><h3 id="_3-4-justificacion-e-impacto-social" tabindex="-1">3.4 Justificación e Impacto Social <a class="header-anchor" href="#_3-4-justificacion-e-impacto-social" aria-label="Permalink to &quot;3.4 Justificación e Impacto Social&quot;">​</a></h3><ul><li><strong>Impacto Social y Comunitario:</strong> Beneficio directo para las familias y agilización de trámites.</li><li><strong>Impacto Tecnológico:</strong> Adopción de tecnologías libres y erradicación de la dependencia de software privativo.</li><li><strong>Vinculación con el Plan de la Patria y las Líneas de Investigación UPTT:</strong> Relación con el objetivo nacional de Soberanía Tecnológica e independencia digital.</li></ul><hr><h2 id="📝-conclusiones-y-entregables-de-la-evaluacion-3" tabindex="-1">📝 Conclusiones y Entregables de la Evaluación 3 <a class="header-anchor" href="#📝-conclusiones-y-entregables-de-la-evaluacion-3" aria-label="Permalink to &quot;📝 Conclusiones y Entregables de la Evaluación 3&quot;">​</a></h2><p>Para la Evaluación 3, el equipo debe consignar el <strong>1er Informe de Avance (Capítulo I)</strong> que incluye:</p><ol><li>Diagrama formal del <strong>Árbol del Problema</strong> y del <strong>Árbol de Objetivos</strong>.</li><li>Redacción completa del <strong>Planteamiento del Problema</strong> con fundamentación empírica.</li><li>Formulación de <strong>Objetivo General y Objetivos Específicos</strong> coherentes con el ciclo de vida del software.</li><li>Justificación e impacto institucional.</li></ol>',15))])}const I=c(m,[["render",g]]);export{v as __pageData,I as default};
